mapper.select:
SELECT user_id FROM im_message_read
WHERE message_id = #{messageId}
ORDER BY read_at ASC

SELECT COUNT(DISTINCT m.msg_id)
FROM im_message_0 m
LEFT JOIN im_message_read mr ON m.msg_id = mr.message_id AND mr.user_id = #{userId}
WHERE (m.to_id = #{userId} OR m.group_id IN (
    SELECT group_id FROM im_group_member WHERE user_id = #{userId}
))
AND m.from_id != #{userId}
AND mr.id IS NULL
AND m.status = 1

    AND (
        (m.to_id = #{userId} AND m.from_id = #{conversationId})
        OR (m.group_id = #{conversationId})
    )
